import bisect

class Solution:
    def findRadius(self, houses: list[int], heaters: list[int]) -> int:
        heaters.sort()
        result = 0
        for house in houses:
            idx = bisect.bisect_left(heaters, house)
            dist = float('inf')
            if idx < len(heaters):
                dist = min(dist, heaters[idx] - house)
            if idx > 0:
                dist = min(dist, house - heaters[idx - 1])
            result = max(result, dist)
        return result

